function [ys_, params, info] = steadystate(ys_, exo_, params)
% Steady state generated by Dynare preprocessor
    info = 0;
    ys_(10)=1;
    ys_(3)=params(14);
    mu_ss=1+params(3);
    epsi_ss=(1+params(3))/params(3);
    ys_(25)=params(5);
    ys_(12)=ys_(10)^(1/(epsi_ss-1));
    ys_(11)=ys_(10)*params(2)/(1-params(2));
    rho_ss=(1-params(1))/params(1);
    ys_(8)=params(6)/(1-params(2));
    ys_(9)=params(7)/(1-params(2));
    ys_(7)=ys_(8)/ys_(9);
    ys_(6)=params(5)/(params(5)+(1-params(2))*ys_(8));
    ys_(21)=1-ys_(6);
    ys_(5)=ys_(7)*ys_(6);
    ys_(4)=params(2)*(1+ys_(5)-ys_(6));
    recruiter_share_ss=(params(2)+(epsi_ss-1)*(params(2)+rho_ss))/(params(2)+epsi_ss*(params(2)+rho_ss));
    w_wR_ss=params(12)/recruiter_share_ss;
    ys_(13)=ys_(3)/w_wR_ss;
    z_ss=ys_(13)*mu_ss/ys_(12);
    surplus_ratio_ss=(params(5)+rho_ss)/(1-params(2))*1/(ys_(9)*params(8));
    ys_(2)=(ys_(13)-ys_(3))/(1+surplus_ratio_ss);
    kappa_ss=ys_(2)*(1-params(8))/params(8)/ys_(9);
    f_e_ss=(1-params(2))*z_ss*(mu_ss-1)*ys_(21)/ys_(10)/(rho_ss+mu_ss*params(2));
    ys_(14)=ys_(12)*f_e_ss/mu_ss;
    ys_(15)=ys_(14)*(params(2)+rho_ss)/(1-params(2));
    ys_(22)=ys_(11)*f_e_ss/z_ss;
    ys_(23)=ys_(21)-ys_(22);
    ys_(16)=ys_(23)*ys_(12)*z_ss;
    ys_(1)=ys_(2)*(1+rho_ss)/(params(2)+rho_ss);
    F_ss=ys_(4)/ys_(1)^(1/params(9));
    ys_(18)=F_ss/(1+params(9))*(ys_(4)/F_ss)^(1+params(9));
    ys_(17)=ys_(16)-ys_(18)-ys_(9)*ys_(5)*kappa_ss;
    ys_(19)=ys_(17)^(-params(4));
    ys_(20)=ys_(16)+ys_(11)*ys_(14);
    ys_(24)=params(12);
    ys_(26)=0;
    ys_(27)=0;
    ys_(29)=0;
    ys_(28)=0;
    ys_(30)=0;
    ys_(31)=0;
    z_imp=0;
    ys_(32)=100*log(ys_(6));
    ys_(33)=100*log(ys_(5));
    ys_(34)=100*log(ys_(7));
    ys_(35)=100*log(ys_(4));
    ys_(36)=100*log(ys_(10));
    ys_(37)=100*log(ys_(11));
    ys_(38)=100*log(ys_(12));
    ys_(39)=100*log(ys_(17));
    ys_(40)=100*log(ys_(20));
    % Auxiliary equations
ys_(41)=ys_(28);
end
